        a, b = b, a % b
    return a

def check_good_set(U):
    if len(U) < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1.
    # Since we are starting with |U|=3, we check gcd(U).
    g = U[0]
    for x in U[1:]:
        g = gcd(g, x)
    if g != 1:
        return False

    # Condition 2: For any two distinct elements, there exists another element that is a divisor of their product.
    N = len(U)
    for i in range(N):
        for j in range(i + 1, N):
            u_i = U[i]
            u_j = U[j]
            product = u_i * u_j

            found_divisor = False
            for k in range(N):
                if k != i and k != j:
                    u_k = U[k]
                    if product % u_k == 0:
                        found_divisor = True
                        break

            if not found_divisor:
                return False

    return True

# Systematic search for |U|=3 solutions up to a reasonable bound (m < 5000)
good_numbers = set()
max_product = 5000

# We search a, b, c such that a*b*c < max_product
# Iterate through the smallest element a
for a in range(1, 30):
    if a > 1000: break
    # Iterate through the middle element b > a
    for b in range(a + 1, 100):
        if a * b > max_product: break
        # Iterate through the largest element c > b
